window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-108"]=[{"id":"set2-yLH2Svgr","fingerprint":"34aafd991767df89","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care dintre următoarele particularități sunt frecvent întâlnite la pacienții care se adaptează cu dificultate la terapia cu proteze mobile?","options":[{"id":"A","text":"Hipertrofia musculaturii masticatorii."},{"id":"B","text":"Coordonare insuficientă a musculaturii aparatului dento-maxilar (ADM)."},{"id":"C","text":"Parafuncții ce duc la instabilitatea protezelor."},{"id":"D","text":"Toleranță scăzută a țesuturilor moi."},{"id":"E","text":"Câmpuri protetice deficitare."}],"correct":["B","C","D","E"],"pages":[280],"source":"set-2"},{"id":"set2-HVWvwBgE","fingerprint":"45bee0ff5a35a08a","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt motivele pentru care unii pacienți edentați total, purtători de proteze, pot solicita inserarea de implante dentare?","options":[{"id":"A","text":"Reducerea duratei tratamentului comparativ cu protezarea convențională."},{"id":"B","text":"Aprecierea nerealistă a condiției de edentat total protezat."},{"id":"C","text":"Reflexe de vomă exagerate declanșate de contactul cu piesele protetice."},{"id":"D","text":"Intoleranța psihologică față de proteze, chiar dacă acestea prezintă o stabilitate acceptabilă."},{"id":"E","text":"Acceptarea garantată de către organism a corpurilor străine inserate."}],"correct":["B","C","D"],"pages":[281],"source":"set-2"},{"id":"set2-1PpCCaWi","fingerprint":"1f292790b1e5220e","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Ce tipuri de proteze cu sprijin implantar sunt menționate ca opțiuni de restaurare protetică pentru edentația totală?","options":[{"id":"A","text":"Proteze mobile, precum supraprotezele menținute și stabilizate prin capse sau pe bare."},{"id":"B","text":"Proteze totale convenționale cu adeziune îmbunătățită."},{"id":"C","text":"Proteze parțiale mobilizate de către pacient sau doar de către medic."},{"id":"D","text":"Punți dentare cimentate pe dinți stâlpi naturali."},{"id":"E","text":"Proteze parțiale fixe."}],"correct":["A","C","E"],"pages":[281],"source":"set-2"},{"id":"set2-4saKYN7r","fingerprint":"d3a3f3b6df7a10d1","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care dintre următoarele afecțiuni sunt considerate contraindicații sistemice absolute pentru tratamentul chirurgical de inserare a implantelor?","options":[{"id":"A","text":"Corticoterapie îndelungată."},{"id":"B","text":"Infarct miocardic recent."},{"id":"C","text":"Tabagism cronic sever."},{"id":"D","text":"Osteomalacie avansată."},{"id":"E","text":"SIDA."}],"correct":["B","C","D"],"pages":[281],"source":"set-2"},{"id":"set2-KwGB14H3","fingerprint":"df684783b4c89250","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Conform clasificării lui Misch și Judy pentru edentații totali, ce caracterizează situația clinică din clasa C?","options":[{"id":"A","text":"La mandibulă, în zona frontală, se pot insera implante cilindrice de dimensiuni scăzute."},{"id":"B","text":"Rezerva osoasă permite inserarea oricărui tip de implant la ambele maxilare."},{"id":"C","text":"La ambele maxilare pot fi inserate implante intraosoase de tip cilindrice sau tronconice cu dimensiuni mai reduse."},{"id":"D","text":"Inserarea implantelor este posibilă doar în asociație cu intervenții de adiție osoasă."},{"id":"E","text":"La maxilar nu este posibilă inserarea de implante endoosoase."}],"correct":["A","E"],"pages":[281],"source":"set-2"},{"id":"set2-dELkDEik","fingerprint":"72d2f5897705ea57","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Ce aspecte trebuie luate în considerare cu discernământ și atenție la stabilirea indicației de inserare a implantelor dentare la pacienții edentați total?","options":[{"id":"A","text":"Prezența unor afecțiuni precum boli cardio-vasculare, osteoporoză sau labilitate psihică."},{"id":"B","text":"Terapia este întotdeauna de scurtă durată și cu risc minim de eșec."},{"id":"C","text":"Faptul că terapia reclamă o serie de intervenții traumatice."},{"id":"D","text":"Costul redus al intervențiilor comparativ cu protezele mobile clasice."},{"id":"E","text":"Vârsta înaintată a pacienților și patologia asociată frecventă."}],"correct":["A","C","E"],"pages":[281],"source":"set-2"},{"id":"set2-aP5fafZK","fingerprint":"aa3928dc51e21420","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Care dintre următoarele condiții este considerată o contraindicație sistemică relativă pentru inserarea implantelor dentare?","options":[{"id":"A","text":"Alcoolism cronic/sever."},{"id":"B","text":"Tulburări ale metabolismului P-Ca."},{"id":"C","text":"Proteză valvulară."},{"id":"D","text":"Radioterapie."},{"id":"E","text":"Diabet sever."}],"correct":["B"],"pages":[281],"source":"set-2"},{"id":"set2-UTeRz540","fingerprint":"4eb879524a9d5c38","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Ce opțiune terapeutică este necesară pentru a putea insera implante la un pacient edentat total încadrat în clasa a patra a clasificării lui Misch și Judy?","options":[{"id":"A","text":"Asocierea cu intervenții de adiție osoasă."},{"id":"B","text":"Utilizarea exclusivă a supraprotezelor pe capse."},{"id":"C","text":"Plasarea de implante intraosoase de tip cilindric cu dimensiuni reduse."},{"id":"D","text":"Utilizarea de implante endoosoase interforaminale."},{"id":"E","text":"Inserarea unui număr mai mare de implante pentru a crește suprafața de contact."}],"correct":["A"],"pages":[281],"source":"set-2"},{"id":"set2-zV2Klfp0","fingerprint":"e634349fd37b86dc","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Conform observațiilor clinice, care este distribuția rezervei osoase la pacienții edentați total care solicită tratament prin implante dentare?","options":[{"id":"A","text":"30% prezintă o rezervă osoasă slabă, 50% o situație acceptabilă și 20% o rezervă osoasă corespunzătoare."},{"id":"B","text":"În situația când pacientul solicită necondiționat o protezare fixă se poate apela la inserarea a 4 - 6 implante în zona frontală maxilară și interforaminală la mandibulă."},{"id":"C","text":"30% prezintă o rezervă osoasă slabă, 20% o situație acceptabilă și 50% o rezervă osoasă corespunzătoare."},{"id":"D","text":"20% prezintă o rezervă osoasă slabă, 50% o situație acceptabilă și 30% o rezervă osoasă corespunzătoare."},{"id":"E","text":"50% prezintă o rezervă osoasă slabă, 30% o situație acceptabilă și 20% o rezervă osoasă corespunzătoare."}],"correct":["A","B"],"pages":[282],"source":"set-2"},{"id":"set2-pd09WyLq","fingerprint":"1962ee21205b2faa","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt motivele pentru care implantele endoosoase se inserează cu precădere în regiunile frontale ale maxilarelor la pacientul edentat total?","options":[{"id":"A","text":"La maxilar, după pierderea dinților din zona de sprijin, planșeul sinusului maxilar se apropie mult de vârful crestei."},{"id":"B","text":"Vascularizația mai bogată din regiunile anterioare ale maxilarelor este esențială pentru succesul pe termen lung al implantelor."},{"id":"C","text":"Osul din regiunile frontale are o densitate superioară care garantează o osteointegrare mai rapidă."},{"id":"D","text":"La mandibulă, procesele de atrofie și resorbție aduc nervul dentar inferior în vecinătatea coamei crestei."},{"id":"E","text":"La maxilar, după pierderea dinților din zona de sprijin, planșeul sinusului maxilar nu se apropie de vârful crestei."}],"correct":["A","D"],"pages":[282],"source":"set-2"},{"id":"set2-pEvxSHqP","fingerprint":"34cfcbce29eb3648","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Ce metodă permite o apreciere exactă a rezervei osoase și stabilirea precisă a locului de inserare a implantelor?","options":[{"id":"A","text":"Realizarea unei machete radiologice dintr-o masă plastică transparentă, ce include markeri metalici."},{"id":"B","text":"Utilizarea modelelor de studiu din gips pentru a simula vizual poziția viitoarelor implante."},{"id":"C","text":"În restaurarea protetică a edentațiilor totale, se preferă supraprotezarea pe două sau, cel puțin, patru implante (all-on-4)."},{"id":"D","text":"Palparea digitală a crestei edentate pentru a stabili lățimea și conturul osos."},{"id":"E","text":"Exclusiv analiza unei ortopantomografii (OPT) pentru determinarea înălțimii osoase disponibile."}],"correct":["A"],"pages":[282],"source":"set-2"},{"id":"set2-oPHlIunM","fingerprint":"3417f25d0fd67abe","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care dintre următoarele afirmații referitoare la restaurările protetice pe implante la pacientul edentat total sunt corecte?","options":[{"id":"A","text":"Suprastructurile protetice pot fi atât proteze fixe, cât și mobile."},{"id":"B","text":"Bara de conjuncție (mezostructura) este cel mai utilizat sistem de ancorare, conectând infrastructura de suprastructură."},{"id":"C","text":"Mezostructurile mandibulare pot fi proiectate liber, fără a respecta cerințe specifice de design."},{"id":"D","text":"Pentru protezările fixe, este obligatorie inserarea de implante și în zonele laterale."},{"id":"E","text":"Inserarea a două implante cilindrice în spațiul interforaminal la mandibulă necesită ca bara de stabilizare să aibă o lungime de minimum 20 mm."}],"correct":["A","B","E"],"pages":[282],"source":"set-2"},{"id":"set2-CvpuIo4G","fingerprint":"58e5f27887ebe535","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Ce condiții trebuie să respecte o bară de conjuncție care unește două implante cilindrice inserate în spațiul interforaminal la mandibulă?","options":[{"id":"A","text":"Bara trebuie să fie plasată întotdeauna deasupra liniei care unește cele două implante."},{"id":"B","text":"Bara de stabilizare trebuie să fie paralelă cu bisectoarea unghiului format de prelungirea crestelor reziduale."},{"id":"C","text":"Bara de stabilizare trebuie să fie perpendiculară pe bisectoarea unghiului format de prelungirea celor două creste reziduale"},{"id":"D","text":"Linia care unește cele două implante să nu fie dispusă în afara arcului crestei."},{"id":"E","text":"Bara de stabilizare trebuie să aibă o lungime de cel puțin 20 mm."}],"correct":["C","D","E"],"pages":[282],"source":"set-2"},{"id":"set2-QozdnL9I","fingerprint":"4b817ec8546e6d6e","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Ce caracteristici definesc implantele subperiostale?","options":[{"id":"A","text":"Au fost cel mai frecvent utilizate între anii 1975 și 1985."},{"id":"B","text":"Bara de stabilizare trebuie să fie perpendiculară pe bisectoarea unghiului format de prelungirea celor două creste reziduale."},{"id":"C","text":"Primul timp operator constă în crearea unui lăcaș intraosos pentru implant."},{"id":"D","text":"Utilizarea lor a fost redusă din cauza prejudiciilor aduse patului osos."},{"id":"E","text":"Inserarea lor se realizează în doi timpi chirurgicali."}],"correct":["D","E"],"pages":[282],"source":"set-2"},{"id":"set2-FfZfKuRk","fingerprint":"7142a9f795e56767","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Care este procedura corectă pentru inserarea unui implant intracortical?","options":[{"id":"A","text":"Se realizează o singură ședință chirurgicală în care implantul prefabricat este plasat sub corticală."},{"id":"B","text":"Implantul se înșurubează direct prin corticală în osul spongios."},{"id":"C","text":"Se inseră un schelet metalic sub periost, care se va sprijini direct pe suprafața osului."},{"id":"D","text":"Inserarea implantelor subperiostale se execută de obicei în doi timpi, primul fiind amprentarea substratului osos."},{"id":"E","text":"Se ridică corticala, se amprentează osul, iar implantul din titan este inserat într-o etapă ulterioară."}],"correct":["E"],"pages":[282],"source":"set-2"},{"id":"set2-f4zWV37f","fingerprint":"7729a3bbea793584","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care este principalul motiv pentru care implantele subperiostale au fost în mare parte abandonate după perioada lor de glorie (1955-1965)?","options":[{"id":"A","text":"Au fost asociate cu prejudicii aduse patului osos, în principal osteoliză."},{"id":"B","text":"Conduceau la incongruența piesei metalice pe câmpul osos și compromiterea tratamentului."},{"id":"C","text":"Compoziția lor din aliaje de aur a devenit prohibitivă din punct de vedere al costului."},{"id":"D","text":"Nu erau adaptate pentru a recepta forțe mari în cazurile de atrofie marcată."},{"id":"E","text":"Procedura de inserare necesita obligatoriu două etape clinice, crescând complexitatea."}],"correct":["A","B"],"pages":[283],"source":"set-2"},{"id":"set2-p05OPCNf","fingerprint":"d52bf4a94e968497","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care dintre următoarele tipuri de design aparțin implantelor intraosoase sub formă de rădăcină (root form)?","options":[{"id":"A","text":"Cilindri."},{"id":"B","text":"Lame."},{"id":"C","text":"Schelete perforate."},{"id":"D","text":"Șuruburi."},{"id":"E","text":"Formă hibridă."}],"correct":["A","D","E"],"pages":[283],"source":"set-2"},{"id":"set2-T4JScZx8","fingerprint":"0ee7842f82b6e902","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Ce parametri constanți stau la baza conceptelor lui Spiekerman pentru tratamentul edentațiilor totale cu proteze pe implante?","options":[{"id":"A","text":"Sprijinul protezei, care poate fi mixt (implantar și muco-osos) sau exclusiv implantar."},{"id":"B","text":"Compoziția aliajului din care este realizat implantul (de exemplu, aliaj de Au-Ag-Cu-Pt)."},{"id":"C","text":"Numărul de implante inserate."},{"id":"D","text":"Condițiile morfologice specifice la maxilar și la mandibulă."},{"id":"E","text":"Distanța dintre implant și creasta reziduală, fixată la 2 mm."}],"correct":["A","C","D"],"pages":[283],"source":"set-2"},{"id":"set2-Kiq4hmWX","fingerprint":"48f927cbb83fe780","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt indicațiile specifice pentru utilizarea implantului transmandibular?","options":[{"id":"A","text":"Osteoporoză asociată cu creastă reziduală atrofică la mandibulă."},{"id":"B","text":"Edentație totală la maxilar cu condiții morfologice nefavorabile."},{"id":"C","text":"Eșecuri anterioare cu diferite tipuri de implante."},{"id":"D","text":"Resorbție medie a crestelor reziduale, cu o înălțime de maximum 10 mm."},{"id":"E","text":"Atrofie accentuată a crestei reziduale la mandibulă, clasa D Misch – Judy."}],"correct":["A","C","E"],"pages":[283],"source":"set-2"},{"id":"set2-qUu4B78f","fingerprint":"4e16aa0702111468","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"În ce altă situație clinică, pe lângă tratamentul atrofiilor mandibulare severe, poate fi utilizat cu succes sistemul de implant transmandibular (TMI)?","options":[{"id":"A","text":"În edentații totale maxilare ce necesită sprijin exclusiv implantar."},{"id":"B","text":"La pacienți supuși radioterapiei."},{"id":"C","text":"Ca mijloc de imobilizare și contenție în fracturi de mandibulă."},{"id":"D","text":"La pacienți care necesită augmentări osoase submucoase extinse."},{"id":"E","text":"Pentru solidarizarea a două implante endoosoase poziționate interforaminal."}],"correct":["B","C"],"pages":[283],"source":"set-2"},{"id":"set2-HzUU79Is","fingerprint":"d61ac7548c16edfd","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt caracteristicile Conceptului I al lui Spikermann pentru supraprotezarea pe implante la mandibulă?","options":[{"id":"A","text":"Bara de solidarizare este distanțată la 2 mm de creasta reziduală."},{"id":"B","text":"Implantele inserate se solidarizează printr-o bară rotundă sau ovalară."},{"id":"C","text":"Implantele sunt poziționate în regiunea premolară pentru o distribuție optimă a forțelor."},{"id":"D","text":"Se indică la pacienții cu resorbție medie sau mare a crestelor reziduale (înălțime maximă 10 mm)."},{"id":"E","text":"Presupune inserarea a patru implante endoosoase pentru un sprijin exclusiv implantar."}],"correct":["A","B","D"],"pages":[283],"source":"set-2"},{"id":"set2-LKgfWyPp","fingerprint":"27917465a3e45290","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"În cadrul procedurii chirurgicale pentru implantul transmandibular, ce element este utilizat pentru fixarea și orientarea inițială a scheletului perforat pe marginea inferioară a mandibulei?","options":[{"id":"A","text":"O bară de conjuncție (mezostructură)."},{"id":"B","text":"Un șurub central."},{"id":"C","text":"Sisteme de menținere și stabilizare integrate în proteză."},{"id":"D","text":"Șuruburi transcorticale de 7, 10 și 13 mm."},{"id":"E","text":"Incizia elipsoidală din regiunea mentonieră."}],"correct":["B"],"pages":[283],"source":"set-2"},{"id":"set2-kEeB_j4V","fingerprint":"85d7d92c75ad633e","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Care este compoziția corectă a aliajului utilizat în sistemul de implant transmandibular (TMI) descris de R.I. Fonseca?","options":[{"id":"A","text":"Ti – 70%, Al – 12,8%, V – 12,2% și Pd – 5%."},{"id":"B","text":"Au – 70%, Ag – 12,8%, Cu – 12,2% și Pd – 5%."},{"id":"C","text":"Au – 70%, Ag – 12,8%, Cu – 12,2% și Pt – 5%."},{"id":"D","text":"Au – 70%, Ag – 15%, Cu – 10% și Pt – 5%."},{"id":"E","text":"Au – 70%, Ag – 12,2%, Cu – 12,8% și Pt – 5%."}],"correct":["C"],"pages":[283],"source":"set-2"},{"id":"set2-E2gaxxHP","fingerprint":"143a5a6b08d1d199","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt caracteristicile unei supraprotezări mandibulare ancorate pe două implante endoosoase poziționate interforaminal?","options":[{"id":"A","text":"Bara de solidarizare prezintă în mod obligatoriu extensii distale bilaterale."},{"id":"B","text":"Proteza poate suferi o mișcare de rotație în jurul axului constituit de bara care solidarizează implantele."},{"id":"C","text":"Necesită dispensarizare activă și reoptimizări repetate datorită tipului de sprijin."},{"id":"D","text":"Este indicată la pacienții cu o înălțime a crestelor edentate de maximum 10 mm."},{"id":"E","text":"Sprijinul protezei este exclusiv implantar, forțele fiind preluate integral de cele două implante."}],"correct":["B","C","D"],"pages":[284],"source":"set-2"},{"id":"set2-dbGpC6_W","fingerprint":"7052989a80887c42","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Ce tip de mezostructură este utilizată într-o supraprotezare pe 4-6 implante, concepută pentru a oferi un sprijin exclusiv implantar și a elimina bascularea?","options":[{"id":"A","text":"O bară fixată cu șuruburi, dar fără extensii, pentru a permite o extindere maximă a bazei protezei pe câmpul protetic."},{"id":"B","text":"Mai mulți butoni individuali, fără solidarizare printr-o bară, pentru a facilita igienizarea."},{"id":"C","text":"O bară cu extensii distale de o parte și de alta, fixată la implante prin șuruburi."},{"id":"D","text":"O bară rotundă simplă, distanțată la 2 mm de creasta reziduală, care permite rotația protezei."},{"id":"E","text":"O bară de secțiune dreptunghiulară care doar acoperă implantele și breșele interimplantare."}],"correct":["C"],"pages":[284],"source":"set-2"},{"id":"set2-RNCTjPPA","fingerprint":"c4e38b22f0eb5336","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"În ce situație clinică este indicată o supraprotezare care utilizează 3-5 implante interforaminal, cu o bară de secțiune rotundă, ovalară sau dreptunghiulară și sprijin mixt?","options":[{"id":"A","text":"Pe creste reziduale mai înguste, arciforme, cu atrofie medie."},{"id":"B","text":"Exclusiv la maxilar, datorită rezervei osoase deficitare."},{"id":"C","text":"În câmpuri protetice cu oferte osoase bune interforaminal și creste atrofiate în zonele de sprijin."},{"id":"D","text":"La câmpuri protetice cu ofertă osoasă bună și relații intermaxilare acceptabile, folosind 4-6 implante."},{"id":"E","text":"La pacienți cu resorbție mare a crestelor, cu o înălțime de maximum 10 mm."}],"correct":["A"],"pages":[284],"source":"set-2"},{"id":"set2-M31KgDF0","fingerprint":"89da830d6d1fa301","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt afirmațiile corecte cu privire la transmiterea forțelor și stabilitatea în diferite tipuri de supraprotezări pe implante?","options":[{"id":"A","text":"Într-un sistem cu 2 implante și bară rotundă, sprijinul este mixt, iar proteza poate suferi rotații."},{"id":"B","text":"Într-un sistem cu 4-6 implante și bară cu extensii distale, transmiterea forțelor se face exclusiv pe implante."},{"id":"C","text":"Stabilitatea este maximă, fără basculare sau rotații, la supraprotezele cu sprijin mixt."},{"id":"D","text":"Sistemul cu 4-6 implante solidarizate cu bară și o supraprotezare este întotdeauna cu sprijin mixt."},{"id":"E","text":"O supraproteză pe 3-5 implante cu sprijin mixt basculează frecvent, necesitând reoptimizări lunare."}],"correct":["A","B"],"pages":[284],"source":"set-2"},{"id":"set2-OQiI3GN2","fingerprint":"1cdb345f20565824","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Care este principalul factor care face ca realizarea protezelor cu sprijin implantar la maxilarul edentat total să fie mai dificilă comparativ cu mandibula?","options":[{"id":"A","text":"Condițiile de igienizare sunt mult mai precare la maxilar."},{"id":"B","text":"Numărul redus de intervenții chirurgicale necesare la mandibulă."},{"id":"C","text":"Imposibilitatea de a obține un sprijin mixt la nivelul maxilarului."},{"id":"D","text":"Dificultatea de a solidariza implantele printr-o bară."},{"id":"E","text":"O rezervă osoasă deficitară, atât calitativ, cât și cantitativ."}],"correct":["E"],"pages":[284],"source":"set-2"},{"id":"set2-IRBlKpgI","fingerprint":"a741c05353801b30","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Ce distanță trebuie menținută între bara de solidarizare a implantelor și creasta reziduală pentru a asigura o igienizare corespunzătoare în cazul unei supraprotezări pe două implante?","options":[{"id":"A","text":"Bara trebuie să fie în contact direct cu creasta reziduală."},{"id":"B","text":"3 mm"},{"id":"C","text":"Distanța nu este importantă pentru igienizare."},{"id":"D","text":"2 mm"},{"id":"E","text":"1 mm"}],"correct":["D"],"pages":[284],"source":"set-2"},{"id":"set2-Efkrl4Aa","fingerprint":"f07b599b80cdbcfa","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt unele dintre modificările osoase specifice maxilarului care pot influența inserarea implantelor dentare?","options":[{"id":"A","text":"O atrofie de tip centrifug, care complică aspectul estetic."},{"id":"B","text":"Creșterea conținutului mineral osos (BMC) după menopauză."},{"id":"C","text":"Apariția de porozități și diminuări de volum la nivelul compactei."},{"id":"D","text":"O diminuare a trabeculării spongioasei."},{"id":"E","text":"Dificultăți fonetice, estetice și igienice cauzate de atrofia centripetă."}],"correct":["C","D"],"pages":[285],"source":"set-2"},{"id":"set2-m7fFvhgF","fingerprint":"b2f4b3e7d3eb4b62","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Pentru un pacient cu atrofie maxilară marcată, care refuză tehnicile de augmentare osoasă și la care retenția unei proteze totale tradiționale este compromisă, ce presupune soluția de tratament corespunzătoare conceptului I?","options":[{"id":"A","text":"Inserarea a 4-6 implante și realizarea unei supraproteze cu sprijin pur implantar, complet răscroită."},{"id":"B","text":"Inserarea a 3-4 implante în zona frontală și realizarea unei proteze fenestrate cu sprijin mixt."},{"id":"C","text":"Inserarea a 6-8 implante și realizarea unei suprastructuri fixe înșurubate."},{"id":"D","text":"Confecționarea unei proteze mobile prevăzute cu călăreți care se opun eficient mișcărilor de basculare și rotație."},{"id":"E","text":"Inserarea a două implante în regiunea canină, solidarizate printr-o bară, și realizarea unei supraproteze extinse."}],"correct":["E"],"pages":[285],"source":"set-2"},{"id":"set2-BrHyV8pq","fingerprint":"b8b051e8d4201350","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care dintre următoarele caracteristici descriu corect conceptul II de protezare cu sprijin implantar la maxilarul superior?","options":[{"id":"A","text":"Este indicat pacienților cu o rezervă osoasă corespunzătoare unei atrofii medii."},{"id":"B","text":"Presupune inserarea a 3-4 implante endoosoase în zona frontală."},{"id":"C","text":"Lungimea implantelor inserate de o parte și de alta a spinei nazale anterioare este de obicei de 11-13 mm."},{"id":"D","text":"Suprastructura are un sprijin pur implantar."},{"id":"E","text":"Supraproteza este obligatoriu extinsă pe toată suprafața de sprijin a câmpului edentat."}],"correct":["A","B"],"pages":[285],"source":"set-2"},{"id":"set2-mVF8B8CP","fingerprint":"f2aff2e9189594b7","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Ce elemente distinctive caracterizează conceptul III de protezare a maxilarului edentat total?","options":[{"id":"A","text":"Stabilitate mare și posibilitatea de a fi igienizată corect de către pacient."},{"id":"B","text":"Transmiterea forțelor exclusiv implantar printr-o suprastructură fixată prin înșurubare."},{"id":"C","text":"Utilizarea a 4-6 implante solidarizate prin bare cu extensii distale."},{"id":"D","text":"Indicarea în cazuri de atrofii marcante ale suportului osos maxilar."},{"id":"E","text":"Realizarea unei supraproteze cu sprijin pur implantar."}],"correct":["A","C","E"],"pages":[285],"source":"set-2"},{"id":"set2-6XtDks11","fingerprint":"0267bf16e9a2077c","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Care este principala caracteristică a suprastructurii protetice în cadrul conceptului IV?","options":[{"id":"A","text":"Este o supraproteză cu sprijin mixt, care poate fi fenestrată."},{"id":"B","text":"Este o supraprotezare fixată prin înșurubare, cu stabilitate maximă."},{"id":"C","text":"Este o supraproteză extinsă pe toată suprafața de sprijin a câmpului edentat."},{"id":"D","text":"Igienizarea acesteia se realizează facil de către pacient, la domiciliu."},{"id":"E","text":"Este o supraproteză mobilizabilă de către pacient, cu sprijin pur implantar."}],"correct":["B"],"pages":[285],"source":"set-2"},{"id":"set2-jBLULecE","fingerprint":"a944342ca6b0adc9","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Asociați corect numărul de implante cu conceptul de protezare corespunzător pentru maxilarul edentat total.","options":[{"id":"A","text":"Conceptul I: 3-4 implante."},{"id":"B","text":"Conceptul II: 4-6 implante."},{"id":"C","text":"Conceptul III: 4-6 implante."},{"id":"D","text":"Conceptul II: 2 implante."},{"id":"E","text":"Conceptul IV: 2-4 implante."}],"correct":["C"],"pages":[285],"source":"set-2"},{"id":"set2-IaoBDR3q","fingerprint":"ec4b021b8d3c244a","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Care este definiția corectă a componentelor unui sistem de restaurare protetică pe implante?","options":[{"id":"A","text":"Infrastructura constă în butoni de presiune și călăreți, mezostructura în coroane telescopate, iar suprastructura în implantul endoosos."},{"id":"B","text":"Infrastructura este restaurarea protetică, mezostructura este implantul endoosos, iar suprastructura este bontul implantului."},{"id":"C","text":"Infrastructura reprezintă restaurarea protetică, mezostructura este compusă din bonturi, iar suprastructura din implanturi endoosoase."},{"id":"D","text":"Infrastructura este reprezentată de implantele endoosoase, mezostructura de bonturile implantelor, iar suprastructura de restaurarea protetică."},{"id":"E","text":"Infrastructura este bontul implantului, mezostructura este bara de solidarizare, iar suprastructura este supraproteza."}],"correct":["D"],"pages":[286],"source":"set-2"},{"id":"set2-P6P38GCn","fingerprint":"20acb3ed7f5fadd8","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt funcțiile principale ale barei utilizate în cadrul mezostructurii unei lucrări protetice pe implante?","options":[{"id":"A","text":"Solidarizează implantele între ele."},{"id":"B","text":"Servește drept matrice pentru butonii de presiune."},{"id":"C","text":"Contribuie la conectarea suprastructurii de infrastructură."},{"id":"D","text":"Asigură retenția îmbunătățită în cazul implantelor solitare."},{"id":"E","text":"Se elaborează exclusiv din mase plastice speciale."}],"correct":["A","C"],"pages":[286],"source":"set-2"},{"id":"set2-YRjnlUf8","fingerprint":"ae579dc08cf79f7e","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Ce tipuri de conexiuni pot fi utilizate între implante (izolate sau solidarizate prin bară) și suprastructura protetică?","options":[{"id":"A","text":"Extensiile distale."},{"id":"B","text":"Coroanele telescopate."},{"id":"C","text":"Magneții."},{"id":"D","text":"Butonii de presiune."},{"id":"E","text":"Călăreții."}],"correct":["B","C","D","E"],"pages":[286],"source":"set-2"},{"id":"set2-Bc6s72wT","fingerprint":"3bfa6c5f13ce05a1","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Referitor la utilizarea butonilor de presiune, care afirmație este corectă?","options":[{"id":"A","text":"Patricea trebuie situată supragingival pentru a facilita igiena."},{"id":"B","text":"Sunt cunoscuți și sub numele de sisteme telescopate."},{"id":"C","text":"Sunt confecționați exclusiv din mase plastice speciale."},{"id":"D","text":"Sunt utilizați în principal atunci când implantele sunt solidarizate prin bare."},{"id":"E","text":"Matricea este componenta care se înșurubează la implant."}],"correct":["A"],"pages":[286],"source":"set-2"},{"id":"set2-NvqUHs8e","fingerprint":"6ea29e08b4c6e450","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"În ce context clinic sunt indicate cu precădere sistemele telescopate?","options":[{"id":"A","text":"Pentru a uni două sau mai multe implante printr-o structură rigidă."},{"id":"B","text":"Când implantele rămân solitare și barele nu pot fi realizate."},{"id":"C","text":"În situațiile în care este necesară o conexiune cu magneți."},{"id":"D","text":"Atunci când se dorește realizarea unor extensii distale."},{"id":"E","text":"Când se optează pentru o supraproteză mobilizabilă fixată prin călăreți."}],"correct":["B"],"pages":[286],"source":"set-2"},{"id":"set2-aBs2nFV_","fingerprint":"69779edea7387215","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Care este adâncimea medie a șanțului periimplantar considerată normală în jurul unui implant sănătos?","options":[{"id":"A","text":"1,3 - 3,8 mm."},{"id":"B","text":"1,5 mm."},{"id":"C","text":"0,2 mm."},{"id":"D","text":"Mai mare de 3,8 mm."},{"id":"E","text":"Sub 1,3 mm."}],"correct":["A"],"pages":[286],"source":"set-2"},{"id":"set2-N5PjvnZW","fingerprint":"9b3e8af7898cf76a","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Ce semnificație clinică are sângerarea în jurul unui implant dentar?","options":[{"id":"A","text":"Apariția sângerării este un indicator fiabil doar după instalarea semnelor histologice de inflamație."},{"id":"B","text":"Sângerarea declanșată mecanic exclude prezența unui șanț periimplantar adânc."},{"id":"C","text":"Sângerarea spontană indică o resorbție osoasă incipientă."},{"id":"D","text":"Sângerarea la examinare este întotdeauna un semn de țesut sănătos."},{"id":"E","text":"Sângerarea spontană apare în faze avansate ale pierderii implantului."}],"correct":["E"],"pages":[286],"source":"set-2"},{"id":"set2-vVOyAEQP","fingerprint":"541e89ae95d484cb","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Care sunt parametrii acceptabili ai pierderii osoase verticale în jurul unui implant osteointegrat?","options":[{"id":"A","text":"O pierdere osoasă de până la 3,8 mm în primul an este considerată fiziologică."},{"id":"B","text":"Absența totală a pierderii osoase pe parcursul primilor 5 ani."},{"id":"C","text":"O pierdere medie de 1,5 mm în primul an, urmată de o pierdere de 0,2 mm/an."},{"id":"D","text":"O pierdere medie de 0,2 mm în primul an, urmată de o pierdere de 1,5 mm/an."},{"id":"E","text":"O pierdere osoasă progresivă care depășește 0,2 mm/an, indiferent de perioada de timp."}],"correct":["C"],"pages":[286],"source":"set-2"},{"id":"set2-useClBjQ","fingerprint":"7b64ba0e44a6eb02","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Ce poate obiectiva o imagine radiotransparentă apărută în jurul unui implant dentar?","options":[{"id":"A","text":"O relație funcțională optimă între implant, bont și suprastructură."},{"id":"B","text":"Instalarea periimplantitei, în diferite grade de evoluție."},{"id":"C","text":"O densitate osoasă crescută a crestei alveolare."},{"id":"D","text":"Succesul terapeutic și o osteointegrare completă."},{"id":"E","text":"O pierdere osoasă verticală în limitele fiziologice."}],"correct":["B"],"pages":[286],"source":"set-2"},{"id":"set2-tcakb5sg","fingerprint":"e3b70a4b7d461f83","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care dintre următoarele reprezintă criterii de succes pentru un implant dentar osteointegrat?","options":[{"id":"A","text":"Prezența unei radiotransparențe periimplantare minime pe radiografie."},{"id":"B","text":"Absența mobilității implantului la testarea clinică."},{"id":"C","text":"Absența durerii persistente sau a proceselor infecțioase legate de implant."},{"id":"D","text":"O pierdere osoasă verticală mai mică de 0.2 mm pe an, după primul an de funcționalitate."},{"id":"E","text":"Rata de succes de 85% după 10 ani de la încărcarea protetică."}],"correct":["B","C","D"],"pages":[287],"source":"set-2"},{"id":"set2-YHGJt6SO","fingerprint":"88845f2d5f6e66e7","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Care este rata maximă acceptabilă de pierdere osoasă verticală anuală în jurul unui implant dentar, după primul an de funcționare, pentru a fi considerat un succes?","options":[{"id":"A","text":"Nu există o limită specificată"},{"id":"B","text":"Mai mică de 0.2 mm"},{"id":"C","text":"Mai mică de 0.5 mm"},{"id":"D","text":"Mai mare de 0.2 mm"},{"id":"E","text":"Exact 0.2 mm"}],"correct":["B"],"pages":[287],"source":"set-2"},{"id":"set2-Vt8WLouk","fingerprint":"36e77b865ff41583","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Ce rate de succes sunt necesare pentru un implant dentar pentru a îndeplini criteriile de succes după 5, respectiv 10 ani de la încărcarea protetică?","options":[{"id":"A","text":"85% după 5 ani și 80% după 10 ani."},{"id":"B","text":"90% după 5 ani și 85% după 10 ani."},{"id":"C","text":"80% după 5 ani și 80% după 10 ani."},{"id":"D","text":"95% după 5 ani și 90% după 10 ani."},{"id":"E","text":"85% după 5 ani și 75% după 10 ani."}],"correct":["A"],"pages":[287],"source":"set-2"},{"id":"set2-MQrjJk_N","fingerprint":"a41f8d3993fc2c5c","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt factorii cheie de care depinde succesul implanto-protetic final, în afara criteriilor specifice ale implantului?","options":[{"id":"A","text":"Planificarea riguroasă a implanturilor în acord cu cea protetică."},{"id":"B","text":"Menținerea ofertei osoase și mucoase strict la nivelul existent, fără intervenții de augmentare."},{"id":"C","text":"Reabilitarea relațiilor mandibulo-craniene și a factorilor funcționali."},{"id":"D","text":"Realizarea unei restaurări protetice exclusiv fixe."},{"id":"E","text":"Abordarea pacientului într-o manieră holistică."}],"correct":["A","C","E"],"pages":[287],"source":"set-2"},{"id":"set2-8Im1-1_U","fingerprint":"be9403ba06351f6d","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care dintre următoarele afecțiuni reprezintă contraindicații sistemice absolute pentru inserarea de implante dentare?","options":[{"id":"A","text":"Osteomalacia avansată"},{"id":"B","text":"Proteza valvulară"},{"id":"C","text":"Infarctul miocardic recent"},{"id":"D","text":"Sindromul imunodeficienței dobândite (SIDA)"},{"id":"E","text":"Corticoterapia îndelungată"}],"correct":["A","B","C"],"pages":[281],"source":"set-2"},{"id":"set2-QedYynl3","fingerprint":"be95818a437f6a1b","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"În clasificarea edentaților total elaborată de Misch și Judy, care sunt caracteristicile clinice definitorii pentru clasa a treia?","options":[{"id":"A","text":"Situația clinică contraindică inserarea oricărui implant fără intervenții prealabile de adiție osoasă."},{"id":"B","text":"Rezerva osoasă permite inserarea oricărui tip de implant, atât la maxilar, cât și la mandibulă."},{"id":"C","text":"Oferta osoasă permite inserarea implantelor cilindrice de dimensiuni scăzute doar în zona frontală mandibulară, inserarea implantelor endoosoase la maxilar fiind imposibilă."},{"id":"D","text":"Implantele endoosoase se pot insera doar în zonele laterale ale ambelor maxilare, în urma unei intervenții de sinus lift."},{"id":"E","text":"La ambele maxilare se pot insera doar implante intraosoase cilindrice sau tronconice de dimensiuni reduse, cu un prognostic rezervat."}],"correct":["C"],"pages":[281],"source":"set-2"},{"id":"set2-nsssgY7Q","fingerprint":"4b78877822d16844","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt regulile biomecanice pe care trebuie să le respecte o bară de stabilizare fixată pe două implante cilindrice inserate în spațiul interforaminal mandibular?","options":[{"id":"A","text":"Bara de stabilizare trebuie să aibă o lungime de minimum 20 mm."},{"id":"B","text":"Bara trebuie să unească cele două implante situate la extremități."},{"id":"C","text":"Bara de stabilizare trebuie să fie paralelă cu bisectoarea unghiului format de prelungirea celor două creste reziduale."},{"id":"D","text":"Bara de stabilizare trebuie să fie perpendiculară pe bisectoarea unghiului format de prelungirea celor două creste reziduale."},{"id":"E","text":"Linia care unește cele două implante extreme trebuie dispusă în afara arcului crestei pentru a asigura stabilitatea."}],"correct":["A","B","D"],"pages":[282],"source":"set-2"},{"id":"set2-ffAJlGYn","fingerprint":"408da095665e0118","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Care sunt proporțiile referitoare la calitatea rezervei osoase la pacienții edentați total care solicită inserarea de implante dentare?","options":[{"id":"A","text":"50% prezintă o rezervă osoasă slabă, 20% o situație acceptabilă și 30% o rezervă osoasă corespunzătoare."},{"id":"B","text":"30% prezintă o rezervă osoasă slabă, 50% o situație acceptabilă și 20% o rezervă osoasă corespunzătoare."},{"id":"C","text":"20% prezintă o rezervă osoasă slabă, 50% o situație acceptabilă și 30% o rezervă osoasă corespunzătoare."},{"id":"D","text":"30% prezintă o rezervă osoasă slabă, 20% o situație acceptabilă și 50% o rezervă osoasă corespunzătoare."},{"id":"E","text":"50% prezintă o rezervă osoasă slabă, 30% o situație acceptabilă și 20% o rezervă osoasă corespunzătoare."}],"correct":["B"],"pages":[282],"source":"set-2"},{"id":"set2-ycTLa-tH","fingerprint":"62bac3e867f8981a","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care dintre următoarele elemente reprezintă particularități clinice sau psihologice ale pacienților edentați total care prezintă dificultăți de adaptare la protezele mobile?","options":[{"id":"A","text":"Reflexele de vomă exagerate declanșate la contactul cu protezele."},{"id":"B","text":"Aprecierea nerealistă a condiției de edentat total protezat."},{"id":"C","text":"Prezența parafuncțiilor care determină instabilitatea pieselor protetice."},{"id":"D","text":"Coordonarea excesivă și spasticitatea musculaturii aparatului dento-maxilar."},{"id":"E","text":"Toleranța crescută a țesuturilor moi de la nivelul câmpului protetic."}],"correct":["A","B","C"],"pages":[281],"source":"set-2"},{"id":"set2-etgtBCBT","fingerprint":"6f0b4f98f53d4910","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt afirmațiile adevărate privind diversele tipuri de implante utilizate în terapia edentației totale?","options":[{"id":"A","text":"Designul implantelor endoosoase impune realizarea tratamentului obligatoriu într-o singură etapă clinică."},{"id":"B","text":"Implantele subperiostale au generat prejudicii patului osos, manifestate în principal prin osteoliză."},{"id":"C","text":"Implantele transosoase se recomandă a fi practicate doar de către chirurgii maxilofaciali."},{"id":"D","text":"Implantele subcorticale se confecționează în laborator dintr-un aliaj de aur, platină și argint."},{"id":"E","text":"Implantele intraosoase au din punct de vedere al designului exclusiv formă de șuruburi sau cilindri."}],"correct":["B","C"],"pages":[282,283],"source":"set-2"},{"id":"set2-aK6IwnAT","fingerprint":"41ecf33e9155592c","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Conceptele de tratament ale edentațiilor totale prin proteze cu sprijin implantar au în vedere anumiți parametri constanți. Care sunt aceștia?","options":[{"id":"A","text":"Sprijinul mixt al protezei (implantar și muco-osos) sau exclusiv implantar."},{"id":"B","text":"Condițiile morfologice specifice la maxilar și la mandibulă."},{"id":"C","text":"Vârsta pacientului și densitatea osoasă la nivelul crestei alveolare."},{"id":"D","text":"Compoziția microcristalină a aliajului utilizat pentru structura implantului."},{"id":"E","text":"Numărul de implante inserate."}],"correct":["A","B","E"],"pages":[282,283],"source":"set-2"},{"id":"set2-fUu-V8du","fingerprint":"d4eab76b0ea6fccc","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt indicațiile tehnicii implantelor transosoase (implantul transmandibular)?","options":[{"id":"A","text":"Osteoporoză asociată cu creastă reziduală atrofică strict la maxilar."},{"id":"B","text":"Edentație totală maxilară cu atrofie severă a crestei alveolare."},{"id":"C","text":"Atrofie accentuată a crestei reziduale la mandibulă, clasa D Misch - Judy."},{"id":"D","text":"Eșecuri înregistrate anterior cu diferite tipuri de implante."},{"id":"E","text":"Mandibulă cu atrofie și fracturi asociate."}],"correct":["C","D","E"],"pages":[282,283],"source":"set-2"},{"id":"set2-NuG6eLnG","fingerprint":"3e1e41742bdbe3b8","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care dintre următoarele afirmații descriu corect caracteristicile și tehnica de inserare a sistemului TMI (Transmandibular Implant)?","options":[{"id":"A","text":"Contraindică aplicarea la pacienții supuși radioterapiei din cauza riscului de osteonecroză."},{"id":"B","text":"Scheletul perforat se fixează exclusiv prin șurubul central, nefiind necesare alte șuruburi transcorticale."},{"id":"C","text":"Este realizat dintr-un aliaj ce conține 70% Au, 12,8% Ag, 12,2% Cu și 5% Pt, cu o structură microcristalină."},{"id":"D","text":"Incizia de abord se realizează în regiunea mentonieră, având o lungime de 2,5 - 3,5 cm."},{"id":"E","text":"Servește ca mijloc de imobilizare și contenție în fracturi de mandibulă asociate."}],"correct":["C","D","E"],"pages":[282,283],"source":"set-2"},{"id":"set2-CDbd2QaI","fingerprint":"d75c66ef9da26f2d","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Ce etapă terapeutică caracterizează implantele intracorticale (subcorticale)?","options":[{"id":"A","text":"Aplicarea directă pe os a unui implant cu suprafața sablată sau acoperită cu hidroxiapatită (HA)."},{"id":"B","text":"Amprentarea suprafeței osoase descoperite se realizează după decolarea periostului, fără ridicarea corticalei."},{"id":"C","text":"Fixarea unui schelet perforat dintr-un aliaj special pe suprafața crestei cu ajutorul unui șurub central."},{"id":"D","text":"Disecția regiunii mentoniere până la evidențierea marginii inferioare a corpului mandibulei."},{"id":"E","text":"Inserarea implantului confecționat în laborator din titan este urmată de refacerea corticalei care îl va acoperi."}],"correct":["E"],"pages":[282,283],"source":"set-2"},{"id":"set2-4zTrpJ_-","fingerprint":"324f5f0c47263afe","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Care este caracteristica esențială a Conceptului III de realizare a supraprotezelor cu sprijin implantar la mandibulă?","options":[{"id":"A","text":"Sprijinul protezei este mixt, muco-osos și cu ancorare pe implante."},{"id":"B","text":"Mezostructura este reprezentată de o bară fixată cu șuruburi, fără extensii distale, și trei călăreți."},{"id":"C","text":"Transmiterea forțelor ocluzale se realizează exclusiv pe implante."},{"id":"D","text":"Infrastructura este constituită strict din două implante inserate în zona canină."},{"id":"E","text":"Supraproteza poate suferi o mișcare de rotație în jurul axului barei de solidarizare."}],"correct":["C"],"pages":[284],"source":"set-2"},{"id":"set2-3FEmau-7","fingerprint":"dd1f58ca3168cca2","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt particularitățile Conceptului I de tratament cu supraproteze pe implante la nivelul maxilarului superior?","options":[{"id":"A","text":"Solidarizarea implantelor se realizează cu o bară cu profil dreptunghiular, ovalar sau rotund."},{"id":"B","text":"Se inseră 3-4 implante endoosoase tronconice în zona frontală, până în dreptul primului premolar."},{"id":"C","text":"Supraproteza se extinde pe toată suprafața de sprijin a câmpului edentat total."},{"id":"D","text":"Este indicat în cazurile de atrofie marcantă a suportului osos, când tehnicile de augmentare sunt refuzate."},{"id":"E","text":"Rezolvarea protetică previne eficient mișcările de basculare și rotație în jurul unui ax frontal."}],"correct":["A","C","D"],"pages":[285],"source":"set-2"},{"id":"set2-SsW7-_HA","fingerprint":"eaadfb3b152c7571","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Ce afirmații reflectă corect modificările anatomice și fiziologice întâlnite în protezarea cu sprijin implantar a maxilarului edentat comparativ cu mandibula?","options":[{"id":"A","text":"Conținutul mineral al oaselor (BMC) este mai scăzut la femei comparativ cu bărbații."},{"id":"B","text":"Maxilarul prezintă o rezervă osoasă deficitară atât cantitativ, cât și calitativ, ceea ce îngreunează realizarea protezelor."},{"id":"C","text":"La nivelul compactei osului maxilar apar porozități și diminuări de volum."},{"id":"D","text":"La nivelul maxilarului apare o creștere a trabeculării spongioasei în primii cinci ani de la menopauză."},{"id":"E","text":"Atrofia maxilarului este de tip centrifug, generând dificultăți estetice și fonetice majore."}],"correct":["A","B","C"],"pages":[285],"source":"set-2"},{"id":"set2-3oO-icXe","fingerprint":"a05a2c3c332ca291","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"În cadrul Conceptului II de protezare cu sprijin implantar la mandibulă, care este abordarea corectă privind mezostructura și caracteristicile sprijinului?","options":[{"id":"A","text":"Sprijinul este mixt, iar mezostructura este reprezentată de o bară ce acoperă implantele și de mai mulți călăreți incluși în proteza mobilă."},{"id":"B","text":"Se bazează pe infrastructuri de 6-8 implante fără necesitatea utilizării unei bare de solidarizare interimplante."},{"id":"C","text":"Mezostructura constă într-o supraprotezare fixată prin înșurubare direct pe implante, fără sprijin pe crestele edentate."},{"id":"D","text":"Supraproteza prezintă un sprijin mixt și basculează în timpul funcției, permițând mișcări complete de rotație."},{"id":"E","text":"Mezostructura include o bară cu extensii distale și cinci călăreți, asigurând sprijin pur implantar."}],"correct":["A"],"pages":[285],"source":"set-2"},{"id":"set2-uasoYQkz","fingerprint":"95b28878f7581360","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care dintre următoarele aspecte definesc Conceptul III de abordare terapeutică cu sprijin implantar pentru maxilarul superior edentat?","options":[{"id":"A","text":"Suprastructura are sprijin pur implantar și este răscroită complet."},{"id":"B","text":"Igienizarea se realizează periodic exclusiv profesional, de către medic, suprastructura neputând fi mobilizată de pacient."},{"id":"C","text":"Implantele sunt solidarizate prin bare ce prezintă două extensii distale de 6-10 mm în regiunea premolarului doi."},{"id":"D","text":"Se inseră 4-6 implante endoosoase în zona frontală, extinzându-se până în dreptul primului premolar."},{"id":"E","text":"Supraproteza beneficiază de un sprijin mixt, extinzându-se pe toată suprafața de sprijin a câmpului edentat."}],"correct":["A","C","D"],"pages":[285],"source":"set-2"},{"id":"set2-Y3tMHggl","fingerprint":"a8cb89d6d9361123","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care dintre următoarele afirmații descriu corect Conceptul II aplicat la maxilarul edentat total?","options":[{"id":"A","text":"Proteza aplicată are un sprijin mixt și poate prezenta fenestrări."},{"id":"B","text":"Implantele sunt solidarizate prin bare fixate prin cimentare de durată."},{"id":"C","text":"Presupune inserarea a 3-4 implante endoosoase tronconice sau cilindrice în zona frontală."},{"id":"D","text":"Se adresează pacienților care prezintă o rezervă osoasă corespunzătoare unei atrofii medii."},{"id":"E","text":"Implantele inserate imediat lângă spina nazală anterioară au de obicei o lungime cuprinsă între 11 și 13 mm."}],"correct":["A","C","D"],"pages":[285],"source":"set-2"},{"id":"set2-i5YjJj6y","fingerprint":"0d30e68374e6c520","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care dintre următoarele afirmații descriu corect elementele și structurile utilizate în protezarea pe implanturi?","options":[{"id":"A","text":"Călăreții, elemente de conexiune asociate barelor, sunt confecționați exclusiv din metale nobile pentru a evita degradarea în mediul bucal."},{"id":"B","text":"Patricea butonilor de presiune se înșurubează la implant și trebuie plasată supragingival pentru a facilita igiena."},{"id":"C","text":"Sistemele telescopate sunt indicate în situațiile în care barele nu pot fi realizate, fiind utilizate de obicei pe implante solitare."},{"id":"D","text":"Suprastructura reprezintă segmentul endoos al sistemului, destinat transmiterii directe a forțelor masticatorii către osul alveolar."},{"id":"E","text":"Infrastructura este constituită din bonturile implantelor, care pot fi solidarizate prin intermediul unei bare."}],"correct":["B","C"],"pages":[286],"source":"set-2"},{"id":"set2-1lWkAcDe","fingerprint":"e5e4943fc301a03f","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care dintre următoarele modificări ale parametrilor clinici și radiologici caracterizează evoluția țesuturilor periimplantare la pacientul protezat?","options":[{"id":"A","text":"Radiotransparența periimplantară decelată radiologic atestă succesul osteointegrării la un an de la încărcare."},{"id":"B","text":"O pierdere medie de 1,5 mm din marginea osoasă se produce în primul an după aplicarea suprastructurii protetice."},{"id":"C","text":"După primul an de funcționare, o pierdere osoasă verticală progresivă de 0,5 mm pe an se încadrează în limitele evoluției fiziologice."},{"id":"D","text":"Sângerarea spontană reprezintă un indicator timpuriu al resorbției osoase incipiente."},{"id":"E","text":"Adâncimea medie a șanțului periimplantar în jurul unui implant sănătos este cuprinsă între 1,3 și 3,8 mm."}],"correct":["B","E"],"pages":[286],"source":"set-2"},{"id":"set2-D_qJ_-Q2","fingerprint":"6ffa0eb42e99121d","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"Care sunt criteriile de succes ale unui implant dentar osteointegrat?","options":[{"id":"A","text":"Absența durerii persistente, a disconfortului și a proceselor infecțioase asociate prezenței implantului."},{"id":"B","text":"Lipsa mobilității implantului, evaluată exclusiv pe baza măsurătorilor radiologice anuale."},{"id":"C","text":"Acceptarea unei radiotransparențe periimplantare reduse pe radiografia efectuată în incidență corectă."},{"id":"D","text":"Pierderea verticală a osului sub 0,2 mm pe an, înregistrată după primul an de funcționalitate a implantului."},{"id":"E","text":"Atingerea unei rate de succes de 85% după 5 ani și de 80% după 10 ani de la încărcarea protetică."}],"correct":["A","D","E"],"pages":[287],"source":"set-2"},{"id":"set2--YVzO11Z","fingerprint":"6c9af4c94611beae","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CS","text":"Care afirmație definește suprastructura în contextul protezării pe implanturi în edentația totală?","options":[{"id":"A","text":"Este reprezentată de restaurarea protetică propriu-zisă, constând într-o supraproteză imobilizată prin înșurubare sau mobilizabilă."},{"id":"B","text":"Reprezintă patricea butonilor de presiune, înșurubată supragingival la nivelul implantului."},{"id":"C","text":"Constituie sistemul de conexiune cu călăreți care solidarizează implantele la nivelul crestei edentate."},{"id":"D","text":"Reprezintă ansamblul implantelor endoosoase inserate în grosimea oaselor maxilare."},{"id":"E","text":"Este constituită din bonturile implantelor solidarizate prin intermediul unei bare."}],"correct":["A"],"pages":[286],"source":"set-2"},{"id":"set2-gEEXNZff","fingerprint":"670606c7e3cfdfc9","chapterId":"set-2","subchapterId":"set2-3.03.5","type":"CM","text":"În cadrul monitorizării pacienților protezați pe implanturi, parametrul sângerării periimplantare prezintă următoarele caracteristici:","options":[{"id":"A","text":"Sângerarea constituie principalul simptom al unei inflamații gingivale, capabil să apară anterior instalării semnelor histologice specifice."},{"id":"B","text":"Sângerarea poate fi declanșată mecanic, manifestându-se inclusiv la examinarea țesuturilor sănătoase."},{"id":"C","text":"Absența sângerării la sondare exclude posibilitatea unor modificări osoase marginale decelabile radiologic."},{"id":"D","text":"Sângerarea la examinare reprezintă simptomul specific fazelor avansate de pierdere a implantului."},{"id":"E","text":"Sângerarea spontană semnalează exclusiv prezența unui șanț periimplantar adânc, stabil pe termen lung."}],"correct":["A","B"],"pages":[286],"source":"set-2"}];
